/**
 * Spawn a PTY-mode bg job. Phase C variant of `spawnBgJob`:
 * instead of detaching with stdio→file, we fork ourselves with
 * `--bg-pty-host <sock> <cols> <rows> -- <ccb-cmd>`. The host process
 * opens a Bun.Terminal, runs the inner ccb in it, and exposes the
 * PTY over a Unix socket. `ccb attach <short>` later connects to
 * that socket via the adopter for true bidirectional UX.
 *
 * Extracted from bg.ts to keep that file under the LOC budget.
 *
 * @dynamicRequire
 */

import { spawn } from 'node:child_process'
import { mkdirSync, rmSync } from 'node:fs'
import { join } from 'node:path'

import chalk from 'chalk'

import { getDefaultLauncher } from '@thyrox/repl/relaunch.js'

export interface SpawnPtyResult {
  short: string
  pid: number
  cmd: readonly string[]
  cwd: string
  startedAt: number
  socketPath: string
  /** Rendezvous (control) socket path — `<jobDir>/rv.sock`. The inner REPL
   *  binds it; the daemon supervisor's rv client connects to it. Persisted
   *  into meta.json so the adopt path can reconnect after a daemon restart. */
  rendezvousSocketPath: string
  /** Always 'pty'. Set as meta.mode by the caller. */
  mode: 'pty'
  /** procStart timestamp; defeats PID recycle. Read sync at spawn time. */
  procStart?: number
  /** ccb version that spawned the worker. */
  cliVersion?: string
}

/**
 * Build the spawn command + env, fork the PTY-host child, and return
 * the metadata the caller persists into meta.json. Caller owns the
 * meta.json write to avoid leaking JobMeta type into this file.
 */
export function spawnPtyHost(opts: {
  short: string
  jobDir: string
  flags: readonly string[]
  directive: string
  cwd: string
  /** Suppress the "backgrounded (pty)" stdout banner. Used by FleetView
   *  dispatch — the new job is surfaced via state.json polling, not
   *  by writing to the terminal (which would corrupt the TUI). */
  quiet?: boolean
  /**
   * Mark this worker as a spare-pool member (sets CCB_SPARE=1 so the inner
   * REPL writes spare-ready.flag and skips its own state.json sync). Mirrors
   * ant's `i1O` mode param (`q === "spare"`) — an EXPLICIT mode, NOT inferred
   * from an empty directive. The left-arrow resume path also spawns with an
   * empty directive (it inherits the transcript via --resume + --fork-session
   * and must NOT re-run a prompt) yet is a real REPL, not a spare; conflating
   * the two on `directive === ''` mislabeled it as a spare. Default false.
   */
  spare?: boolean
}): SpawnPtyResult {
  mkdirSync(opts.jobDir, { recursive: true })
  const socketPath = join(opts.jobDir, 'pty.sock')
  // Rendezvous (control) socket — the out-of-band channel the inner REPL
  // binds to push authoritative state/done/heartbeat to the daemon
  // supervisor (ant 4291.js server ← 5016.js naK client). Sits alongside
  // pty.sock in the flat per-job dir; the inner REPL reads
  // THYROX_BG_RENDEZVOUS_SOCK to know where to bind. See
  // daemon/socketPaths.ts getRendezvousSocketPath.
  const rendezvousSocketPath = join(opts.jobDir, 'rv.sock')

  // Outer: ccb --bg-pty-host <sock> <cols> <rows> -- <inner ccb>
  // Inner: ccb [user flags] "<directive>"  (full REPL, directive as
  // positional → Commander parses it as [prompt] which the REPL
  // pre-seeds into PromptInput on launch). Mirrors ant's behaviour:
  // the user can attach mid-conversation and continue interactively.
  //
  // Spare-pool path: caller passes directive="" to spawn a worker that
  // idles at empty prompt (waiting for a CTRL `claim` frame to inject
  // the real intent later). For that case we omit the directive arg
  // entirely so Commander doesn't see a literal "" positional (which
  // would auto-submit an empty turn). Source: ant `m_H` "spare" mode.
  const innerArgs =
    opts.directive === ''
      ? [...opts.flags]
      : [...opts.flags, opts.directive]
  // Source: ant 5286.js uKO() — `return D$() ? [process.execPath] :
  // [process.execPath, process.argv[1]]`. D$ = isBunStandalone. Both
  // `bun cli.js` and the compiled standalone binary go through one
  // codepath that prepends `[process.argv[1]]` only when NOT standalone.
  //
  // ccb previously used `process.argv0.endsWith('bun')` for this branch,
  // which BREAKS in compiled standalone binaries because Bun's compile
  // mode sets argv0='bun' (so the embedded runtime can find itself). The
  // heuristic mis-classified standalone as bun-script mode, then prepended
  // process.argv[1] (= the first user CLI flag, e.g. "who am i") in
  // front of --bg-pty-host. The spawn line ended up looking like
  // `bun --bg-pty-host …` which, when resolved through PATH, found the
  // user's local bun and tried to load "--bg-pty-host" as a script — exit
  // immediately, pty.sock never appears, fleetAttach polls 10s, and the
  // user's right-arrow keystrokes leak into the terminal as ^[[C because
  // stdin raw mode was already released during ink unmount.
  //
  // getDefaultLauncher({pinToCurrentBinary:true}) is ccb's `Pb` —
  // mirrors ant 5286.js uKO + 4835.js `Pb({pinToCurrentBinary:!0})`.
  // pinToCurrentBinary skips the auto-update symlink redirect: the bg
  // worker must boot the SAME binary that spawned it, otherwise an
  // auto-update mid-spawn would race the worker against a different
  // version's wire protocol.
  const launcher = getDefaultLauncher({ pinToCurrentBinary: true })
  const cmd = launcher.cmd
  const prefixArgs = launcher.prefixArgs
  const cols = String(process.stdout.columns || 200)
  const rows = String(process.stdout.rows || 50)
  const hostArgs = [
    ...prefixArgs,
    '--bg-pty-host',
    socketPath,
    cols,
    rows,
    '--',
    cmd,
    ...prefixArgs,
    ...innerArgs,
  ]
  const fullCmd = [cmd, ...hostArgs]

  const env: NodeJS.ProcessEnv = {
    ...process.env,
    THYROX_CODE_SESSION_KIND: 'bg',
    THYROX_CODE_BG_JOB_SHORT: opts.short,
    FORCE_COLOR: '3',
    COLORTERM: 'truecolor',
    BROWSER: 'true',
    THYROX_JOB_DIR: opts.jobDir,
    THYROX_BG_BACKEND: 'pty',
    // Rendezvous control socket the inner REPL binds (ant eaK sets the same
    // THYROX_BG_RENDEZVOUS_SOCK env). The bg REPL's useBgRendezvousServer
    // hook reads this to start the out-of-band control channel; absent it,
    // the worker degrades to the legacy disk-poll path.
    THYROX_BG_RENDEZVOUS_SOCK: rendezvousSocketPath,
    THYROX_BG_SOURCE: 'cli',
    CLAUDE_ENABLE_STREAM_WATCHDOG: '1',
    THYROX_CODE_SESSION_NAME: opts.short,
    // Spare-pool marker: an EXPLICIT spare flag (ant `i1O` mode "spare"),
    // not inferred from an empty directive. Read by useSpareReadyMarker
    // (writes spare-ready.flag) + useBgFleetStateSync (skips its own
    // state.json sync — we don't want the worker writing `state: 'working'`
    // while it's actually idle waiting). Source: ant 4774.js spare workers
    // run with `m_H(..., "spare", ...)`. The left-arrow resume path also
    // spawns directive='' but is a real REPL, so it must stay UNmarked.
    ...(opts.spare === true ? { CCB_SPARE: '1' } : {}),
  }

  // Strip the FleetView-subsystem reader marker so it NEVER leaks into a
  // dispatched worker. `CCB_FLEET_INPROCESS_REMOUNT=1` activates the rust
  // stdin reader (App.useNativeReader) + the orphan-check stdin bypass — both
  // are correct ONLY for the foreground process driving FleetView. The
  // standalone `ccb agents` handler sets it PROCESS-GLOBALLY before dispatching
  // workers (unlike the left-arrow bridge, which dispatches before setting it),
  // so without this delete every bg worker would inherit it and wrongly run the
  // reader against its OWN pty slave fd 0 + skip its orphan check. spawnPtyHost
  // is the single chokepoint for all PTY spawns (spawnBgPty / respawnJob /
  // bgDaemon all funnel here), so deleting once here covers every path.
  delete env.CCB_FLEET_INPROCESS_REMOUNT

  const child = spawn(cmd, hostArgs, {
    cwd: opts.cwd,
    env,
    detached: true,
    stdio: ['ignore', 'ignore', 'ignore'],
  })
  child.unref()

  if (child.pid === undefined) {
    rmSync(opts.jobDir, { recursive: true, force: true })
    process.stderr.write(`Failed to spawn pty-host: ${fullCmd.join(' ')}\n`)
    process.exit(1)
  }

  // Pretty hint output: cyan short, dim hints (ant 4649.js tw6).
  // Suppressed when called from FleetView (TUI owns the screen).
  if (opts.quiet !== true) {
    const d = (l: string, r: string) => chalk.dim(`  ${l.padEnd(26)}${r}`)
    process.stdout.write(
      [
        `backgrounded (pty) · ${chalk.cyan(opts.short)}`,
        d(`ccb attach ${opts.short}`, 'open in this terminal (bidirectional)'),
        d(`ccb stop ${opts.short}`, 'stop this session (SIGTERM)'),
        d(`ccb rm   ${opts.short}`, 'remove the job directory'),
        '',
      ].join('\n'),
    )
  }

  // readProcStart is sync (reads /proc or runs ps); cheap enough at spawn time.
  // Imported lazily to avoid pulling daemon package into a path this file
  // could be called from without daemon present.
  const { readProcStart } = require('@thyrox/daemon/bgWorkerRegistry.js') as typeof import('@thyrox/daemon/bgWorkerRegistry.js')
  return {
    short: opts.short,
    pid: child.pid,
    cmd: fullCmd,
    cwd: opts.cwd,
    startedAt: Date.now(),
    socketPath,
    rendezvousSocketPath,
    mode: 'pty',
    procStart: readProcStart(child.pid) || undefined,
    cliVersion: MACRO.VERSION,
  }
}

/**
 * Reconstruct a `(flags, directive)` pair from a stored job meta.cmd.
 *
 * Two cmd shapes (both pre-stripped of bg flags by splitBgArgs):
 *   detached: [interpreter, cli.js?, ...userFlags, '-p', directive]
 *   pty:      [interpreter, cli.js?, '--bg-pty-host', sock, cols, rows,
 *              '--', interpreter, cli.js?, ...userFlags, directive]
 *
 * Detached uses `-p directive` so the marker is unambiguous. Pty uses
 * the directive as a positional (REPL prompt-arg) so we extract the
 * LAST non-flag arg from the inner-ccb tail.
 */
export function extractRespawnArgs(cmd: readonly string[]): {
  flags: string[]
  directive: string
} | null {
  let i = cmd[0]?.endsWith('bun') ? 2 : 1
  let isPty = false
  if (cmd[i] === '--bg-pty-host') {
    isPty = true
    const dashDash = cmd.indexOf('--', i)
    if (dashDash < 0) return null
    i = dashDash + 1
    if (i < cmd.length && cmd[i]?.endsWith('bun')) i += 2
    else i += 1
  }

  if (!isPty) {
    // detached: -p marker
    const pIdx = cmd.lastIndexOf('-p')
    if (pIdx < i || pIdx === cmd.length - 1) return null
    return {
      flags: [...cmd.slice(i, pIdx)],
      directive: cmd.slice(pIdx + 1).join(' '),
    }
  }

  // pty: scan inner args, separating flags+values from positional.
  // Reuse splitBgArgs's flag-with-value table: flags like --model
  // consume the next arg as their value rather than treating it as a
  // positional.
  const inner = cmd.slice(i)
  return parseInnerArgs(inner)
}

/**
 * Same flag-detection rules as bg/argParse.ts splitBgArgs, minus the
 * --bg-* prefix stripping (those don't appear in stored cmds).
 */
function parseInnerArgs(args: readonly string[]): {
  flags: string[]
  directive: string
} | null {
  const FLAGS_WITH_VALUE = new Set([
    '--model',
    '--permission-mode',
    '--session-id',
    '--add-dir',
    '-r',
    '--resume',
    '--max-turns',
    '--cwd',
    '--debug-file',
    '--mcp-config',
    '--append-system-prompt',
    '--strict-mcp-config',
    '--include-partial-messages',
  ])
  const dashDashIdx = args.indexOf('--')
  const before = dashDashIdx >= 0 ? args.slice(0, dashDashIdx) : args
  const after = dashDashIdx >= 0 ? args.slice(dashDashIdx + 1) : []
  const flags: string[] = []
  const positionals: string[] = []
  for (let k = 0; k < before.length; k++) {
    const a = before[k]!
    if (a.startsWith('-')) {
      flags.push(a)
      if (a.includes('=')) continue
      const next = before[k + 1]
      if (next !== undefined && !next.startsWith('-') && FLAGS_WITH_VALUE.has(a)) {
        flags.push(next)
        k++
      }
      continue
    }
    positionals.push(a)
  }
  const directive = [...positionals, ...after].join(' ')
  if (!directive) return null
  return { flags, directive }
}

/**
 * PTY socket adopter — speaks the bg-pty-host wire protocol.
 *
 * Daemon-less ccb's `ccb attach <short>` opens this directly against
 * the PTY host's socket; a future Phase C+ daemon would also use it
 * for cross-process supervision. Mirrors ant 4704.js rj6, but trimmed
 * down: ccb has no daemon supervisor so the respawn-detection /
 * upgrade-tracking / roster-hooks branches are removed. What's kept:
 *
 *   - Connect with backoff (WXK=30 attempts, PXK=[100,250,500,1000,2000])
 *   - ENOENT detection (socket file gone) → caller-visible error
 *   - Hello-handshake receipt (capture replPid + version)
 *   - Buffer queue while disconnected (cap 2MB before drop)
 *   - Per-client backpressure: writableLength > 1 MiB → destroy
 *   - onData / onExit pub-sub callbacks
 *   - write / resize / kill / dispose API surface
 *   - SIGKILL escalation 5s after SIGTERM
 *
 * @dynamicRequire
 */

import { type Socket, connect } from 'node:net'

import {
  CTRL_TAG,
  DATA_TAG,
  type CtrlFrame,
  createFrameDecoder,
  encodeCtrlFrame,
  encodeDataFrame,
  FRAME_SIZE_CAP,
} from './ptyFrame.js'

const RECONNECT_BACKOFF_MS = [100, 250, 500, 1000, 2000] as const
const MAX_RECONNECT_ATTEMPTS = 30
const QUEUE_CAP_BYTES = 2 * FRAME_SIZE_CAP // 2 * qiH = 2 MiB
const CLIENT_BACKPRESSURE_BYTES = 1024 * 1024
const SIGTERM_GRACE_MS = 5000

export interface PtyAdopter {
  /** Currently-known REPL pid (from hello frame). 0 if not yet seen. */
  replPid(): number
  /** Currently-known REPL version (from hello frame). '' if not yet seen. */
  replVersion(): string
  /** Send raw bytes to the PTY (will be decoded as user input). Takes a
   *  Buffer, NOT a string: stdin bytes (esp. multi-byte UTF-8 like CJK) must
   *  pass through verbatim. A string round-trip (toString('binary') at the
   *  caller + Buffer.from(s,'utf8') here) double-encoded high bytes and
   *  corrupted CJK input. */
  write(b: Buffer): void
  /** Send a resize ctrl frame. */
  resize(cols: number, rows: number): void
  /** Send a kill ctrl frame. SIGTERM auto-escalates to SIGKILL after 5s. */
  kill(sig: 'SIGTERM' | 'SIGKILL'): void
  /** Tear down the adopter (closes socket, cancels timers). */
  dispose(): void
  /** Subscribe to PTY output (bytes from the host). */
  onData(cb: (chunk: Buffer) => void): { dispose: () => void }
  /** Subscribe to host exit notification. */
  onExit(
    cb: (info: { exitCode: number; signal?: string }) => void,
  ): { dispose: () => void }
  /** Subscribe to host heartbeat ctrl-frames (every 5s while alive). */
  onHeartbeat(cb: (info: { ts: number; state?: string }) => void): { dispose: () => void }
}

interface AdopterEvent<T> {
  emit(value: T): void
  subscribe(cb: (value: T) => void): () => void
}

function makeEvent<T>(): AdopterEvent<T> {
  const subs = new Set<(value: T) => void>()
  return {
    emit(value: T): void {
      for (const cb of subs) cb(value)
    },
    subscribe(cb: (value: T) => void): () => void {
      subs.add(cb)
      return () => subs.delete(cb)
    },
  }
}

/**
 * Open an adopter against the PTY socket at `socketPath`. Returns
 * immediately; the connection happens asynchronously and any data
 * sent via `write/resize/kill` before connect completes is queued.
 */
export function createPtyAdopter(socketPath: string): PtyAdopter {
  const onDataEvent = makeEvent<Buffer>()
  const onExitEvent = makeEvent<{ exitCode: number; signal?: string }>()
  const onHeartbeatEvent = makeEvent<{ ts: number; state?: string }>()

  let socket: Socket | undefined
  let pendingFrames: Buffer[] = []
  let pendingBytes = 0
  let connected = false
  let disposed = false
  let attempt = 0
  let reconnectTimer: NodeJS.Timeout | undefined
  let drainTimer: NodeJS.Timeout | undefined
  let backpressureTimer: NodeJS.Timeout | undefined
  let sigkillTimer: NodeJS.Timeout | undefined
  let helloPid = 0
  let helloVersion = ''

  function clearTimers(): void {
    if (drainTimer) {
      clearTimeout(drainTimer)
      drainTimer = undefined
    }
    if (backpressureTimer) {
      clearTimeout(backpressureTimer)
      backpressureTimer = undefined
    }
  }

  function notifyExit(exitCode: number, signal?: string): void {
    if (disposed) return
    disposed = true
    if (sigkillTimer) {
      clearTimeout(sigkillTimer)
      sigkillTimer = undefined
    }
    clearTimers()
    socket?.destroy()
    socket = undefined
    onExitEvent.emit({ exitCode, signal })
  }

  function enqueueOrSend(frame: Buffer): void {
    if (socket && !socket.destroyed) {
      const ok = socket.write(frame)
      if (!ok) {
        // backpressure — schedule destroy if drain doesn't fire in 10s
        // (ant XW3 = 10000), and immediate destroy if the buffer crosses
        // CLIENT_BACKPRESSURE_BYTES (ant GXK).
        if (!drainTimer) {
          drainTimer = setTimeout(() => {
            drainTimer = undefined
            socket?.destroy()
          }, 10_000)
          drainTimer.unref()
        }
        if (
          !backpressureTimer &&
          socket.writableLength > CLIENT_BACKPRESSURE_BYTES
        ) {
          backpressureTimer = setTimeout(() => {
            backpressureTimer = undefined
            if (
              socket &&
              !socket.destroyed &&
              socket.writableLength > CLIENT_BACKPRESSURE_BYTES
            ) {
              clearTimers()
              socket.destroy()
            }
          }, 50) // ant PW3 = 50ms grace
          backpressureTimer.unref()
        }
      }
      return
    }
    // Not connected — queue. Drop oldest if over cap.
    if (pendingBytes + frame.length > QUEUE_CAP_BYTES) return
    pendingFrames.push(frame)
    pendingBytes += frame.length
  }

  function handleFrame(frame: { kind: number; payload?: Buffer; ctrl?: CtrlFrame }): void {
    if (frame.kind === DATA_TAG && frame.payload) {
      onDataEvent.emit(frame.payload)
    } else if (frame.kind === CTRL_TAG && frame.ctrl) {
      const c = frame.ctrl
      if (c.t === 'hello') {
        helloPid = c.replPid
        helloVersion = c.version
      } else if (c.t === 'live') {
        // No-op; live just signals that ring buffer replay is done.
      } else if (c.t === 'exit') {
        notifyExit(c.code, c.signal)
      } else if (c.t === 'heartbeat') {
        onHeartbeatEvent.emit({ ts: c.ts, state: c.state })
      }
    }
  }

  function tryConnect(): void {
    if (disposed || connected) return
    const sock = connect(socketPath)
    let opened = false
    sock.on('error', err => {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
        // Socket file is gone — host died or never started.
        // Bubble up as exit so the caller can give up. ant 4704.js:95
        // would retry here; daemon-less ccb has no host to wait for.
        if (!opened) notifyExit(-1, 'ENOENT')
      }
      sock.destroy()
    })
    sock.once('close', () => {
      if (socket === sock) {
        socket = undefined
        connected = false
        clearTimers()
      }
      if (!disposed && !opened) {
        // Connection failed before opening — schedule retry.
        scheduleReconnect()
      }
    })
    sock.once('connect', () => {
      opened = true
      connected = true
      attempt = 0
      socket = sock
      sock.on('drain', clearTimers)
      // Flush queued frames.
      const queued = pendingFrames
      pendingFrames = []
      pendingBytes = 0
      for (const f of queued) enqueueOrSend(f)
    })
    const decoder = createFrameDecoder(handleFrame, () => sock.destroy())
    sock.on('data', decoder)
  }

  function scheduleReconnect(): void {
    if (disposed || reconnectTimer) return
    if (attempt >= MAX_RECONNECT_ATTEMPTS) {
      notifyExit(-1, 'reconnect-exhausted')
      return
    }
    const delay =
      RECONNECT_BACKOFF_MS[Math.min(attempt, RECONNECT_BACKOFF_MS.length - 1)]!
    attempt++
    reconnectTimer = setTimeout(() => {
      reconnectTimer = undefined
      tryConnect()
    }, delay)
    reconnectTimer.unref()
  }

  // Kick off the initial connection.
  tryConnect()

  return {
    replPid: () => helloPid,
    replVersion: () => helloVersion,
    write(buf: Buffer): void {
      if (disposed) return
      // Frame body cap is 1 MiB; chunk if larger.
      const chunkSize = FRAME_SIZE_CAP - 1
      for (let i = 0; i < buf.length; i += chunkSize) {
        enqueueOrSend(encodeDataFrame(buf.subarray(i, i + chunkSize)))
      }
    },
    resize(cols: number, rows: number): void {
      if (disposed) return
      enqueueOrSend(encodeCtrlFrame({ t: 'resize', cols, rows }))
    },
    kill(sig: 'SIGTERM' | 'SIGKILL'): void {
      if (disposed) return
      enqueueOrSend(encodeCtrlFrame({ t: 'kill', sig }))
      if (sig === 'SIGTERM') {
        if (sigkillTimer) clearTimeout(sigkillTimer)
        sigkillTimer = setTimeout(() => {
          sigkillTimer = undefined
          if (!disposed) {
            enqueueOrSend(encodeCtrlFrame({ t: 'kill', sig: 'SIGKILL' }))
          }
        }, SIGTERM_GRACE_MS)
        sigkillTimer.unref()
      }
    },
    dispose(): void {
      if (disposed) return
      disposed = true
      if (reconnectTimer) {
        clearTimeout(reconnectTimer)
        reconnectTimer = undefined
      }
      if (sigkillTimer) {
        clearTimeout(sigkillTimer)
        sigkillTimer = undefined
      }
      clearTimers()
      socket?.destroy()
      socket = undefined
    },
    onData(cb): { dispose: () => void } {
      const off = onDataEvent.subscribe(cb)
      return { dispose: off }
    },
    onExit(cb): { dispose: () => void } {
      const off = onExitEvent.subscribe(cb)
      return { dispose: off }
    },
    onHeartbeat(cb): { dispose: () => void } {
      const off = onHeartbeatEvent.subscribe(cb)
      return { dispose: off }
    },
  }
}
